engine.shapeEmailTemplates:
function shapeEmailTemplates(rows) {
  var out = {
    myName: "",
    useFullName: false,
    thirdParty: { subject: "", body: "" },
    requester:  { subject: "", body: "" },
    byType: {},
  };
  if (!Array.isArray(rows)) return out;
  rows.forEach(function (r) {
    if (!r || !r.id) return;
    if (r.id === "thirdParty") out.thirdParty = { subject: r.subject || "", body: r.body || "" };
    else if (r.id === "requester") out.requester = { subject: r.subject || "", body: r.body || "" };
    else if (r.id === "byType" && r.byType) out.byType = r.byType;
    else if (r.id === "settings") {
      out.myName = r.myName || "";
      out.useFullName = !!r.useFullName;
    }
  });
  return out;
}

// Per-type lookup with side-default fallback. FROM v2 _getEmailTmplForType.

engine.emailTmplForType:
function emailTmplForType(tmpl, typeKey, side) {
  if (tmpl && tmpl.byType && tmpl.byType[typeKey] && tmpl.byType[typeKey][side]) {
    return tmpl.byType[typeKey][side];
  }
  return (tmpl && tmpl[side]) || { subject: "", body: "" };
}

