// Build the gmail compose URL — token substitution + CC dedup. FROM v2
// gmailBtn.onclick (line 20576). Pure: takes form + tmpl, returns string.

engine.buildGmailUrl:
function buildGmailUrl(form, tmpl) {
  var isToRequester = form.dest === "req";
  var side = isToRequester ? "requester" : "thirdParty";
  var typeKey = form.type || "";
  var active = emailTmplForType(tmpl, typeKey, side);
  if (!active.subject && !active.body) active = defaultTmpl(side);
  var subj = active.subject || "";
  var body = active.body || "";

  var entity = form.entity || "Colgate";
  var tpEntity = form.third_party_entity || "[Third Party Entity]";
  var tpFullName = form.contact_full_name || "[Contact]";
  var tpFirst = String(tpFullName).trim().split(/\s+/)[0];
  var tpEmail = (form.contact_email || "").trim();
  var cpRef = form.cp_ref || "N/A";
  var reqFirst = String(form.requester_name || "[Requester]").trim().split(/\s+/)[0];
  var today = new Date().toLocaleDateString();
  var myName = (tmpl && tmpl.myName || "").trim();
  if (tmpl && !tmpl.useFullName) myName = myName.split(/\s+/)[0] || myName;

  var map = {
    "\\[Entity\\]": entity,
    "\\[TP Entity\\]": tpEntity,
    "\\[Type\\]": form.type || "",
    "\\[CP Ref\\]": cpRef,
    "\\[Date\\]": today,
    "\\[TP Contact\\]": tpFirst,
    "\\[Requester\\]": reqFirst,
    "\\[My Name\\]": myName,
  };
  Object.keys(map).forEach(function (k) {
    var re = new RegExp(k, "g");
    subj = subj.replace(re, map[k]);
    body = body.replace(re, map[k]);
  });

  // CC list — always include tech_agreements@colpal.com, dedupe vs TO.
  var to = isToRequester ? (form.requester_email || "") : tpEmail;
  var ccList = [];
  if (form.requester_email && form.requester_email.length > 3 && !isToRequester) {
    ccList.push(form.requester_email);
  }
  if (form.additional_ccs) {
    var matches = String(form.additional_ccs).match(/([a-zA-Z0-9._-]+@[a-zA-Z0-9._-]+\.[a-zA-Z0-9._-]+)/gi);
    if (matches) ccList.push.apply(ccList, matches);
  }
  ccList.push("tech_agreements@colpal.com");
  var seen = {};
  var toLower = String(to).toLowerCase().trim();
  var uniq = ccList.filter(function (e) {
    var s = String(e).toLowerCase().trim();
    if (!s || s === toLower || seen[s]) return false;
    seen[s] = true;
    return true;
  });
  return "https://mail.google.com/mail/?view=cm&fs=1" +
    "&to=" + encodeURIComponent(to) +
    "&cc=" + encodeURIComponent(uniq.join(",")) +
    "&su=" + encodeURIComponent(subj) +
    "&body=" + encodeURIComponent(body);
}

// FROM v2 line 20428 — fuzzy-match agreement type from raw text against a
// list of options. Returns the best-scoring index, or -1 if no match.
// Used by the view to pre-select the type dropdown from AI-extracted text.

engine.matchAgTypeIndex:
function matchAgTypeIndex(rawText, options) {
  var raw = String(rawText || "").toLowerCase().replace(/[^a-z ]/g, "").trim();
  if (!raw) return -1;
  var rules = [
    { key: "research", score: 100 }, { key: "disclosure", score: 100 },
    { key: "confidential", score: 100 }, { key: "nda", score: 100 },
    { key: "material", score: 100 }, { key: "transfer", score: 50 },
    { key: "mta", score: 100 }, { key: "master", score: 100 },
    { key: "service", score: 30 }, { key: "amendment", score: 100 },
    { key: "clinical", score: 100 }, { key: "joint", score: 100 },
    { key: "development", score: 50 }, { key: "agreement", score: 0 },
  ];
  var bestIdx = -1, bestScore = 0;
  for (var i = 0; i < options.length; i++) {
    var opt = String(options[i] || "").toLowerCase();
    var s = 0;
    if (opt === raw) s += 500;
    for (var k = 0; k < rules.length; k++) {
      if (raw.indexOf(rules[k].key) !== -1 && opt.indexOf(rules[k].key) !== -1) s += rules[k].score;
    }
    if (opt.indexOf("master") !== -1 && raw.indexOf("master") === -1) s -= 50;
    if (s > bestScore) { bestScore = s; bestIdx = i; }
  }
  return bestScore > 0 ? bestIdx : -1;
}

// Engine entry. View calls this to build everything it needs — keeps the
// DOM-side code free of business logic.

engine.analyze:
function analyze(input, providers) {
  var rows = (input && input.templateRows) || [];
  return Promise.resolve({
    templates: shapeEmailTemplates(rows),
    overview: "",
    provenance: {
      kernelVersion: (window.eli && window.eli.kernelVersion) || "v3",
      toolVersion: "v3.0",
      docHash: null,
      timestamp: Date.now(),
    },
  });
}

view.renderComposer:
function renderComposer(opts) {
  var mount = opts.mount || document.getElementById("_eli3_dashboard_root");
  if (!mount) return;
  var prefill = opts.prefill || {};
  var agTypes = opts.agTypes || [];
  var requesters = opts.requesters || []; // [{id, name, email}]
  var defaultDest = opts.defaultDest || "tp"; // "tp" | "req"
  var autoSelectId = opts.autoSelectId == null ? null : String(opts.autoSelectId);
  var matchAgTypeIndex = opts.matchAgTypeIndex || function () { return -1; };
  var onBack = opts.onBack || function () {};
  var onOpenGmail = opts.onOpenGmail || function () {};
  var onSaveRequester = opts.onSaveRequester || function () {};
  var onDeleteRequester = opts.onDeleteRequester || function () {};
  var onPersistPrefill = opts.onPersistPrefill || function () {};

  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }

  // Entity normalization. AI sometimes returns full legal names ("Hill's
  // Pet Nutrition"); the dropdown only has Colgate | Hill's.
  var entityRaw = String(prefill.colgate_entity || prefill.entity || "");
  var isHills = /hill|nutrition/i.test(entityRaw);

  var typeOpts = '<option value="">— Select —</option>' +
    agTypes.map(function (t) { return '<option value="' + _esc(t) + '">' + _esc(t) + '</option>'; }).join("");

  var hideManual = requesters.length > 0 && autoSelectId !== "add_other";
  var reqOptionsHtml = '<option value="">— Select Saved —</option>' +
    requesters.map(function (r) {
      var selected = (autoSelectId !== null && String(r.id) === autoSelectId) ? " selected" : "";
      return '<option value="' + _esc(r.id) + '" data-email="' + _esc(r.email || "") + '"' + selected + '>' + _esc(r.name || r.id) + '</option>';
    }).join("") +
    '<option value="add_other">+ Add other / new…</option>';

  mount.innerHTML = "";
  var root = document.createElement("div");
  root.className = "_eli3_ae_root";
  root.innerHTML =
    '<div class="_eli3_ae_bar">' +
      '<button class="_eli3_ae_back">←</button>' +
      '<div class="_eli3_ae_title">✉️ Contract Emailer</div>' +
    '</div>' +
    '<div class="_eli3_ae_form">' +
      '<div class="_eli3_ae_dest">' +
        '<label class="_eli3_ae_dest_opt"><input type="radio" name="_eli3_ae_dest" value="tp"' +
          (defaultDest === "tp" ? " checked" : "") + '><span>Third Party</span></label>' +
        '<label class="_eli3_ae_dest_opt"><input type="radio" name="_eli3_ae_dest" value="req"' +
          (defaultDest === "req" ? " checked" : "") + '><span>Requester</span></label>' +
      '</div>' +
      '<div class="_eli3_ae_grid2">' +
        '<div>' +
          '<label class="_eli3_ae_label">Entity</label>' +
          '<select class="_eli3_ae_input" id="_eli3_ae_entity">' +
            '<option value="Colgate"' + (!isHills ? " selected" : "") + '>Colgate</option>' +
            '<option value="Hill\'s"' + (isHills ? " selected" : "") + '>Hill\'s</option>' +
          '</select>' +
        '</div>' +
        '<div>' +
          '<label class="_eli3_ae_label">Type</label>' +
          '<select class="_eli3_ae_input" id="_eli3_ae_type">' + typeOpts + '</select>' +
        '</div>' +
      '</div>' +
      '<label class="_eli3_ae_label">Third Party Entity</label>' +
      '<input type="text" class="_eli3_ae_input" id="_eli3_ae_tpentity" value="' + _esc(prefill.third_party_entity || "") + '">' +
      '<div id="_eli3_ae_tpcontact" class="_eli3_ae_grid2"' + (defaultDest === "tp" ? "" : ' style="display:none;"') + '>' +
        '<div>' +
          '<label class="_eli3_ae_label">TP Full Name</label>' +
          '<input type="text" class="_eli3_ae_input" id="_eli3_ae_tpname" value="' + _esc(prefill.contact_full_name || "") + '">' +
        '</div>' +
        '<div>' +
          '<label class="_eli3_ae_label">TP Email</label>' +
          '<input type="text" class="_eli3_ae_input" id="_eli3_ae_tpemail" value="' + _esc(prefill.contact_email || "") + '">' +
        '</div>' +
      '</div>' +
      '<div class="_eli3_ae_req_box">' +
        '<div class="_eli3_ae_req_head">' +
          '<span>REQUESTER</span>' +
          '<button type="button" class="_eli3_ae_req_del" id="_eli3_ae_req_del">🗑️ Remove name</button>' +
        '</div>' +
        '<select class="_eli3_ae_input" id="_eli3_ae_req_sel">' + reqOptionsHtml + '</select>' +
        '<div id="_eli3_ae_req_manual" class="_eli3_ae_req_manual"' + (hideManual ? ' style="display:none;"' : '') + '>' +
          '<input type="text" class="_eli3_ae_input" id="_eli3_ae_req_name" placeholder="Full Name">' +
          '<input type="text" class="_eli3_ae_input" id="_eli3_ae_req_email" placeholder="Email Address">' +
          '<div class="_eli3_ae_req_manual_btns">' +
            '<button type="button" class="_eli3_ae_skip" id="_eli3_ae_req_save">💾 Save & Select</button>' +
            '<button type="button" class="_eli3_ae_skip" id="_eli3_ae_req_use">⚡ Use Once</button>' +
          '</div>' +
        '</div>' +
      '</div>' +
      '<label class="_eli3_ae_label">Additional CCs <span class="_eli3_ae_hint">(comma-separated)</span></label>' +
      '<textarea class="_eli3_ae_input _eli3_ae_ccs" id="_eli3_ae_ccs" placeholder="Name &lt;email&gt;, ..."></textarea>' +
      '<label class="_eli3_ae_label">CP Ref #</label>' +
      '<input type="text" class="_eli3_ae_input" id="_eli3_ae_ref" value="' + _esc(prefill.cp_ref || "") + '">' +
      '<div class="_eli3_ae_actions">' +
        '<button type="button" class="_eli3_ae_skip" id="_eli3_ae_home">← Home</button>' +
        '<button type="button" class="_eli3_ae_btn" id="_eli3_ae_open">' +
          '<span class="_eli3_ae_btn_icon">🚀</span>' +
          '<span class="_eli3_ae_btn_label">Open Gmail Draft</span>' +
        '</button>' +
      '</div>' +
    '</div>';

  root.querySelector("._eli3_ae_back").onclick = onBack;
  root.querySelector("#_eli3_ae_home").onclick = onBack;

  var entitySel = root.querySelector("#_eli3_ae_entity");
  var typeSel   = root.querySelector("#_eli3_ae_type");
  var tpEntInp  = root.querySelector("#_eli3_ae_tpentity");
  var tpContact = root.querySelector("#_eli3_ae_tpcontact");
  var tpNameInp = root.querySelector("#_eli3_ae_tpname");
  var tpEmailInp= root.querySelector("#_eli3_ae_tpemail");
  var reqSel    = root.querySelector("#_eli3_ae_req_sel");
  var reqManual = root.querySelector("#_eli3_ae_req_manual");
  var reqNameInp= root.querySelector("#_eli3_ae_req_name");
  var reqEmailInp= root.querySelector("#_eli3_ae_req_email");
  var ccsInp    = root.querySelector("#_eli3_ae_ccs");
  var refInp    = root.querySelector("#_eli3_ae_ref");

  // Pre-select the agreement type dropdown via fuzzy match (engine helper).
  var rawType = prefill.type || prefill.agreement_type || "";
  if (rawType && typeSel.options.length) {
    var optTexts = [];
    for (var i = 0; i < typeSel.options.length; i++) optTexts.push(typeSel.options[i].text);
    var idx = matchAgTypeIndex(rawType, optTexts);
    if (idx !== -1) typeSel.selectedIndex = idx;
  }
  // Pre-select requester by name. FROM v2 line 20475.
  if (prefill.requester_name && reqSel) {
    var found = false;
    for (var ri = 0; ri < reqSel.options.length; ri++) {
      if (reqSel.options[ri].text.toLowerCase() === String(prefill.requester_name).toLowerCase()) {
        reqSel.selectedIndex = ri; found = true; break;
      }
    }
    if (!found) {
      reqSel.value = "add_other";
      reqManual.style.display = "";
      reqNameInp.value = prefill.requester_name;
      if (prefill.requester_email) reqEmailInp.value = prefill.requester_email;
    }
  }

  // Toggle TP-contact section.
  Array.prototype.forEach.call(root.querySelectorAll('input[name="_eli3_ae_dest"]'), function (rb) {
    rb.onchange = function () { tpContact.style.display = rb.value === "tp" ? "" : "none"; };
  });
  reqSel.onchange = function () {
    var addOther = reqSel.value === "add_other";
    reqManual.style.display = addOther ? "" : "none";
  };

  root.querySelector("#_eli3_ae_req_save").onclick = function () {
    var name = reqNameInp.value.trim();
    var email = reqEmailInp.value.trim();
    if (!name || !email) { if (typeof showToast === "function") showToast("⚠️ Enter name + email first", "warn"); return; }
    onSaveRequester({ name: name, email: email });
  };
  root.querySelector("#_eli3_ae_req_use").onclick = function () {
    reqManual.style.display = "none";
  };
  root.querySelector("#_eli3_ae_req_del").onclick = function (e) {
    e.preventDefault();
    var id = reqSel.value;
    if (!id || id === "add_other") { if (typeof showToast === "function") showToast("Select a saved name first", "warn"); return; }
    onDeleteRequester(id);
  };

  var openBtn = root.querySelector("#_eli3_ae_open");
  openBtn.onclick = function () {
    var dest = (root.querySelector('input[name="_eli3_ae_dest"]:checked') || {}).value || "tp";
    var entity = entitySel.value;
    var type = typeSel.value;
    var tpEntity = tpEntInp.value.trim();
    var tpName = tpNameInp.value.trim();
    var tpEmail = tpEmailInp.value.trim();
    var reqName = "", reqEmail = "";
    if (reqSel.value === "add_other" || reqSel.value === "") {
      reqName = reqNameInp.value.trim();
      reqEmail = reqEmailInp.value.trim();
    } else {
      var opt = reqSel.options[reqSel.selectedIndex];
      reqName = (opt && opt.text) || "";
      reqEmail = (opt && opt.dataset && opt.dataset.email) || "";
    }
    var ccs = ccsInp.value || "";
    var cpRef = refInp.value.trim();

    onPersistPrefill({
      colgate_entity: entity,
      type: type,
      agreement_type: type,
      third_party_entity: tpEntity,
      contact_full_name: tpName,
      contact_email: tpEmail,
      cp_ref: cpRef,
    });

    openBtn.disabled = true;
    var origLabel = openBtn.querySelector("._eli3_ae_btn_label");
    var prev = origLabel.textContent;
    origLabel.textContent = "Opening…";
    Promise.resolve(onOpenGmail({
      dest: dest,
      entity: entity,
      type: type,
      third_party_entity: tpEntity,
      contact_full_name: tpName,
      contact_email: tpEmail,
      requester_name: reqName,
      requester_email: reqEmail,
      cp_ref: cpRef,
      additional_ccs: ccs,
    })).then(function () {
      setTimeout(function () {
        openBtn.disabled = false;
        origLabel.textContent = prev;
      }, 1500);
    }).catch(function () {
      openBtn.disabled = false;
      origLabel.textContent = prev;
    });
  };

  mount.appendChild(root);
}

jsonTools.init:
function init(eli) {
  if (!eli.events) eli.events = { guard: function (fn) { return fn; }, safeAsync: function (p) { return p; } };
  var bundle = eli.tools._loaded["auto_emailer"];
  if (!bundle) return;
  var renderComposer = bundle._eliViewFns && bundle._eliViewFns.renderComposer;
  var shapeEmailTemplates = bundle._eliEngineFns && bundle._eliEngineFns.shapeEmailTemplates;
  var buildGmailUrl = bundle._eliEngineFns && bundle._eliEngineFns.buildGmailUrl;
  var matchAgTypeIndex = bundle._eliEngineFns && bundle._eliEngineFns.matchAgTypeIndex;

  if (!renderComposer || !shapeEmailTemplates || !buildGmailUrl) {
    eli.log.event("tool", "auto_emailer_load_failed", {
      hasView: !!renderComposer,
      hasShape: !!shapeEmailTemplates,
      hasBuildUrl: !!buildGmailUrl,
    });
    return;
  }

  function _recordStatSafe(name) {
    try {
      if (eli.stats && typeof eli.stats.record === "function") eli.stats.record(name);
    } catch (e) {
      eli.log.event("tool", "auto_emailer_stat_failed", { stat: name, msg: e && e.message });
    }
  }

  // FROM v2 line 20290 — persist user-edited values back to doc settings
  // so the next emailer open (any user, any machine) skips AI roundtrip.
  function _persistDocPrefill(patch) {
    if (!patch) return;
    try {
      var s = Office.context.document.settings;
      var current = s.get("EliEmailerPrefill") || {};
      Object.keys(patch).forEach(function (k) {
        if (patch[k] == null || patch[k] === "") delete current[k];
        else current[k] = patch[k];
      });
      s.set("EliEmailerPrefill", current);
      if (typeof s.saveAsync === "function") {
        s.saveAsync(function (res) {
          if (res && res.status !== Office.AsyncResultStatus.Succeeded) {
            eli.log.event("tool", "auto_emailer_persist_failed", { msg: res.error && res.error.message });
          }
        });
      }
    } catch (e) {
      eli.log.event("tool", "auto_emailer_persist_threw", { msg: e && e.message });
    }
  }

  function _readDocPrefill() {
    try {
      var cached = Office.context.document.settings.get("EliEmailerPrefill");
      if (cached && typeof cached === "object") return cached;
    } catch (e) { /* tolerate */ }
    return {};
  }

  // Open the composer. `seed` overrides doc-settings prefill (used when
  // build_draft hands off after save).
  function _open(seed) {
    if (!eli.ai || !eli.ai.hasApiKey()) {
      // Emailer doesn't directly call AI, but agreement_types data and
      // future AI-prefill paths assume the kernel is API-key-warm.
      // Keep this soft — open anyway, just with a hint.
      eli.log.event("tool", "auto_emailer_open_no_ai_key", {});
    }
    var mount = document.getElementById("_eli3_dashboard_root");
    var prefillBase = seed || _readDocPrefill();
    if (seed) {
      // Layer doc-settings on top for fields seed didn't populate
      // (typical: build_draft seeds entity/type/tp/ref but not contact/req).
      var stored = _readDocPrefill();
      ["contact_full_name", "contact_email", "requester_name", "requester_email", "additional_participants"]
        .forEach(function (k) {
          if (stored[k] && !prefillBase[k]) prefillBase[k] = stored[k];
        });
    }

    // Pull agreement types + saved requesters + email templates in parallel.
    Promise.all([
      eli.events.safeAsync(eli.storage.getAll("agreement_types"), "auto_emailer.ag_types"),
      eli.events.safeAsync(eli.storage.getAll("requesters"),      "auto_emailer.requesters"),
      eli.events.safeAsync(eli.storage.getAll("email_templates"), "auto_emailer.templates"),
    ]).then(function (results) {
      var agRows  = results[0] || [];
      var reqRows = results[1] || [];
      var tplRows = results[2] || [];
      var agTypes = agRows
        .filter(function (r) { return r && !r.pseudo; })
        .map(function (r) { return r.label || r.name || r.id; })
        .filter(Boolean);
      var requesters = reqRows
        .filter(function (r) { return r && r.id && (r.name || r.email); })
        .map(function (r) { return { id: String(r.id), name: r.name || "", email: r.email || "" }; });
      var templates = shapeEmailTemplates(tplRows);

      _renderWith({
        mount: mount,
        prefill: prefillBase,
        agTypes: agTypes,
        requesters: requesters,
        templates: templates,
        defaultDest: "tp",
        autoSelectId: null,
      });
    });
  }

  function _renderWith(state) {
    renderComposer({
      mount: state.mount,
      prefill: state.prefill || {},
      agTypes: state.agTypes,
      requesters: state.requesters,
      defaultDest: state.defaultDest,
      autoSelectId: state.autoSelectId,
      matchAgTypeIndex: matchAgTypeIndex,
      onBack: function () {
        if (eli.dashboard && typeof eli.dashboard.goHome === "function") eli.dashboard.goHome();
        else if (eli.dashboard && typeof eli.dashboard.render === "function") eli.dashboard.render();
      },
      onPersistPrefill: _persistDocPrefill,
      onSaveRequester: eli.events.guard(function (newReq) {
        var id = String(Date.now());
        var row = { id: id, name: newReq.name, email: newReq.email };
        eli.events.safeAsync(eli.storage.put("requesters", row), "auto_emailer.req_save").then(function () {
          if (typeof showToast === "function") showToast("✅ Requester saved", "ok");
          state.requesters = state.requesters.concat([row]);
          state.autoSelectId = id;
          _renderWith(state);
        });
      }, "auto_emailer.req_save_outer"),
      onDeleteRequester: function (id) {
        eli.ui.confirm({
          title: "Delete Requester?",
          message: "This removes them from your saved list permanently.",
          variant: "danger",
        }).then(function (ok) {
          if (!ok) return;
          eli.events.safeAsync(eli.storage.delete("requesters", id), "auto_emailer.req_del").then(function () {
            state.requesters = state.requesters.filter(function (r) { return String(r.id) !== String(id); });
            state.autoSelectId = null;
            if (typeof showToast === "function") showToast("🗑️ Removed", "ok");
            _renderWith(state);
          });
        });
      },
      onOpenGmail: function (form) {
        var url = buildGmailUrl(form, state.templates || shapeEmailTemplates([]));
        _recordStatSafe("emailsDrafted");
        if (eli.activity && eli.activity.add) {
          eli.activity.add({
            type: "auto-emailer", icon: "✉️", label: "Auto Emailer · Draft",
            summary: "Drafted " + (form.dest === "req" ? "to requester" : "to TP") + " · " + (form.type || "?"),
            payload: { dest: form.dest, type: form.type, third_party: form.third_party_entity },
          });
        }
        try {
          if (Office.context.ui && typeof Office.context.ui.openBrowserWindow === "function") {
            Office.context.ui.openBrowserWindow(url);
          } else {
            window.open(url, "_blank");
          }
        } catch (e) {
          window.open(url, "_blank");
        }
        return Promise.resolve();
      },
    });
  }

  // Register channels:
  //   tile / app_auto_emailer       — main click from dashboard
  //   auto_emailer:compose          — programmatic launch with a seed
  //                                    payload (used by build_draft post-save)
  eli.register({
    tile: { app_auto_emailer: function () {
      _recordStatSafe("appOpenedAutoEmailer");
      _open(null);
    } },
    auto_emailer: { compose: function (seed) {
      _recordStatSafe("appOpenedAutoEmailer");
      _open(seed || null);
    } },
  });

  eli.log.event("tool", "auto_emailer_initialized", {});
}

jsonTools.css:
/* auto_emailer tool styles. Injected as <style data-tool="auto_emailer">. */

._eli3_ae_root {
  display: flex; flex-direction: column;
  width: 100%; height: 100%;
  background: #fff;
  overflow: hidden;
  box-sizing: border-box;
}
/* Standard tool-hub header — dark navy banner with gold accent rule. */
._eli3_ae_bar {
  flex: 0 0 auto;
  display: flex; align-items: center; gap: 10px;
  padding: 12px 14px;
  background: linear-gradient(135deg, #0d1b2a 0%, #1b263b 100%);
  border-bottom: 3px solid #c9a227;
}
._eli3_ae_back {
  background: none; border: none; cursor: pointer;
  font: 400 22px/1 'Inter', sans-serif; color: #cbd5e1;
  padding: 0 4px;
  transition: color 0.15s;
}
._eli3_ae_back:hover { color: #f2d866; }
._eli3_ae_title {
  flex: 1;
  font: 800 16px/1.2 'Georgia', serif;
  color: #ffffff;
  letter-spacing: 0.2px;
}

/* Form body */
._eli3_ae_form {
  flex: 1 1 auto;
  overflow-y: auto;
  padding: 14px;
  display: flex; flex-direction: column; gap: 6px;
}
._eli3_ae_label {
  font: 700 11px/1.2 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.4px;
  color: #0f172a;
  margin-top: 6px;
}
._eli3_ae_input {
  width: 100%;
  padding: 8px 10px;
  border: 1px solid #cbd5e1;
  background: #fff;
  font: 500 13px/1.3 'Inter', sans-serif;
  color: #0f172a;
  box-sizing: border-box;
  outline: none;
}
._eli3_ae_input:focus {
  border-color: #1565c0;
  box-shadow: 0 0 0 2px rgba(21, 101, 192, 0.18);
}
._eli3_ae_grid2 {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}

/* Destination (TP / Requester) toggle */
._eli3_ae_dest {
  display: flex; gap: 18px;
  padding: 10px 12px;
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  margin-bottom: 6px;
}
._eli3_ae_dest_opt {
  display: inline-flex; align-items: center; gap: 6px;
  font: 600 12px/1 'Inter', sans-serif;
  color: #1e293b;
  cursor: pointer;
}
._eli3_ae_dest_opt input[type="radio"] {
  margin: 0; accent-color: #1565c0;
}

/* Requester picker box */
._eli3_ae_req_box {
  margin-top: 10px;
  padding: 10px 12px;
  background: #eff6ff;
  border: 1px solid #93c5fd;
}
._eli3_ae_req_head {
  display: flex; justify-content: space-between; align-items: center;
  margin-bottom: 6px;
  font: 700 10px/1 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.5px;
  color: #1565c0;
}
._eli3_ae_req_del {
  background: none; border: none;
  color: #c62828;
  font: 700 9px/1 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.4px;
  cursor: pointer;
}
._eli3_ae_req_del:hover { color: #8e1d1d; text-decoration: underline; }
._eli3_ae_req_manual {
  margin-top: 10px;
  padding-top: 10px;
  border-top: 1px dashed #93c5fd;
  display: flex; flex-direction: column; gap: 6px;
}
._eli3_ae_req_manual_btns {
  display: flex; gap: 8px;
  margin-top: 4px;
}
._eli3_ae_req_manual_btns ._eli3_ae_skip { flex: 1; }

/* CCs textarea */
._eli3_ae_ccs {
  font-family: 'JetBrains Mono', monospace;
  height: 56px;
  resize: vertical;
}
._eli3_ae_hint {
  font: 400 10px/1 'Inter', sans-serif;
  color: #94a3b8;
  text-transform: none;
  letter-spacing: 0;
  margin-left: 4px;
}

/* Action row — Skip / Open Gmail Draft */
._eli3_ae_actions {
  display: flex;
  gap: 8px;
  margin-top: 14px;
}
._eli3_ae_skip {
  flex: 1;
  background: linear-gradient(180deg, #fff 0%, #f1f5f9 100%);
  border: 1px solid #cbd5e1;
  font: 700 11px/1 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.4px;
  color: #475569;
  padding: 10px 14px;
  cursor: pointer;
  transition: all 0.15s;
}
._eli3_ae_skip:hover {
  background: linear-gradient(180deg, #f8fafc 0%, #e2e8f0 100%);
  color: #0f172a;
  border-color: #94a3b8;
}
._eli3_ae_btn {
  flex: 1.6;
  display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  background: linear-gradient(135deg, #1565c0 0%, #0d47a1 100%);
  color: #fff;
  border: 1px solid #0d47a1;
  font: 700 12px/1 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.5px;
  padding: 10px 14px;
  cursor: pointer;
  transition: all 0.15s;
  box-shadow: 0 2px 6px rgba(21, 101, 192, 0.25);
}
._eli3_ae_btn:hover:not(:disabled) {
  background: linear-gradient(135deg, #1d4ed8 0%, #1565c0 100%);
  transform: translateY(-1px);
  box-shadow: 0 4px 12px rgba(21, 101, 192, 0.35);
}
._eli3_ae_btn:disabled { opacity: 0.6; cursor: progress; }
._eli3_ae_btn_icon { font-size: 14px; line-height: 1; }
._eli3_ae_btn_label { white-space: nowrap; }
